// Assembles the deployable folder release/ from the standalone build.
// Layout on the server (application root of "Setup Node.js App"):
//   server.js          Passenger startup file, generated by Next standalone
//   .next/             server bundle and static assets
//   node_modules/      traced runtime dependencies only
//   public/            public files
//   dist/cron.js       cron entry point, dist/migrate.js migration runner
//   drizzle/           SQL migrations
import { cpSync, existsSync, lstatSync, readdirSync, readFileSync, realpathSync, rmSync, statSync, writeFileSync } from "node:fs";
import { execSync } from "node:child_process";

const out = "release";
const required = [".next/standalone/server.js", "dist/cron.js", "dist/migrate.js"];
for (const file of required) {
  if (!existsSync(file)) {
    console.error(`Fichier manquant : ${file}. Lancez pnpm build puis pnpm build:cron.`);
    process.exit(1);
  }
}

rmSync(out, { recursive: true, force: true });
// Symlinks are skipped here: the package aliases are materialized below.
cpSync(".next/standalone", out, { recursive: true, filter: (source) => !lstatSync(source).isSymbolicLink() });
cpSync(".next/static", `${out}/.next/static`, { recursive: true });
cpSync("public", `${out}/public`, { recursive: true });
cpSync("dist", `${out}/dist`, { recursive: true });
cpSync("drizzle", `${out}/drizzle`, { recursive: true });
cpSync("scripts/check-release-pdf.mjs", `${out}/scripts/check-release-pdf.mjs`);
cpSync("scripts/backup.sh", `${out}/scripts/backup.sh`);

// Turbopack loads external packages through hashed aliases such as
// .next/node_modules/shiki-<hash>, created as absolute symlinks to the build
// machine. They are replaced by real copies so the release works anywhere,
// whatever the upload method (rsync or FTP). Their own dependencies resolve
// from the release node_modules folder by the usual parent lookup.
function materializeAliases(dir, target) {
  if (!existsSync(dir)) return 0;
  let count = 0;
  for (const entry of readdirSync(dir)) {
    const source = `${dir}/${entry}`;
    const destination = `${target}/${entry}`;
    if (lstatSync(source).isSymbolicLink()) {
      rmSync(destination, { recursive: true, force: true });
      // The traced copy in the standalone folder can be partial: the package is
      // taken whole from the project node_modules (same relative path).
      const resolved = realpathSync(source).replace(/\\/g, "/");
      const relative = resolved.slice(resolved.lastIndexOf("/node_modules/") + "/node_modules/".length);
      const nested = resolved.includes("/node_modules/") ? resolved.split("/node_modules/").slice(1).join("/node_modules/") : relative;
      const full = existsSync(`node_modules/${nested}/package.json`) ? `node_modules/${nested}` : resolved;
      cpSync(full, destination, { recursive: true, dereference: true });
      aliasDependencies.push(...Object.keys(JSON.parse(readFileSync(`${destination}/package.json`, "utf8")).dependencies ?? {}));
      count += 1;
    } else if (entry.startsWith("@") && statSync(source).isDirectory()) {
      count += materializeAliases(source, destination);
    }
  }
  return count;
}
const aliasDependencies = [];

// Next file tracing misses parts of some packages: platform specific native
// bindings (optional dependencies of @node-rs/argon2 and sharp) and ESM
// entries loaded at runtime (fontkit for @react-pdf). These packages are
// shipped whole, with their full dependency closure. node_modules is hoisted
// (pnpm nodeLinker: hoisted) and built on Linux x64 in CI, like the host.
const FULL_PACKAGES = ["@node-rs/argon2", "sharp", "@react-pdf/renderer"];

function readManifest(name) {
  const file = `node_modules/${name}/package.json`;
  return existsSync(file) ? JSON.parse(readFileSync(file, "utf8")) : null;
}

const shipped = new Set();
function shipWithDependencies(name) {
  if (shipped.has(name)) return;
  const manifest = readManifest(name);
  // Optional dependencies for other platforms are simply not installed.
  if (!manifest) return;
  shipped.add(name);
  cpSync(`node_modules/${name}`, `${out}/node_modules/${name}`, { recursive: true, dereference: true });
  for (const dependency of Object.keys({ ...manifest.dependencies, ...manifest.optionalDependencies })) {
    shipWithDependencies(dependency);
  }
}

for (const name of FULL_PACKAGES) {
  if (!readManifest(name)) {
    console.error(`Paquet introuvable dans node_modules : ${name}.`);
    process.exit(1);
  }
  shipWithDependencies(name);
}
if (![...shipped].some((name) => name.startsWith("@node-rs/argon2-"))) {
  console.error("Aucun binaire natif @node-rs/argon2 trouvé : la connexion échouerait en production.");
  process.exit(1);
}
console.log(`${shipped.size} paquets copiés en entier (${FULL_PACKAGES.join(", ")} et dépendances).`);

const aliases = materializeAliases(".next/standalone/.next/node_modules", `${out}/.next/node_modules`);
// Dependencies of the aliased packages are shipped whole as well.
for (const name of aliasDependencies) shipWithDependencies(name);
console.log(`${aliases} alias de paquets externes copiés dans .next/node_modules, ${shipped.size} paquets complets au total.`);

// Defensive clean-up: only runtime files are deployed.
const notShipped = [
  "src", "tests", "docs", "cron", "release", "portfolio_data", ".claude",
  "README.md", "CLAUDE.md", "components.json", "drizzle.config.ts", "eslint.config.mjs",
  "next.config.ts", "postcss.config.mjs", "vitest.config.mts", "tsconfig.json", "tsconfig.tsbuildinfo",
  "pnpm-lock.yaml", "pnpm-workspace.yaml", "release-server.log",
];
for (const entry of notShipped) rmSync(`${out}/${entry}`, { recursive: true, force: true });

// Never ship local environment files.
for (const file of [".env", ".env.local", ".env.production.local"]) {
  rmSync(`${out}/${file}`, { force: true });
}

let commit = "unknown";
try {
  commit = execSync("git rev-parse --short HEAD").toString().trim();
} catch {
  // Not a git checkout.
}
const leftovers = readdirSync(out).filter((entry) => /[.](md|log|ts|tsx)$/.test(entry));
if (leftovers.length > 0) {
  console.error(`Fichiers inattendus dans la release : ${leftovers.join(", ")}`);
  process.exit(1);
}
writeFileSync(`${out}/RELEASE`, `${commit}\n${new Date().toISOString()}\n`);

// Size guard: the application is under 150 MB. Anything far bigger means a
// stray file (an archive or a copy of the project) was picked up by tracing.
function sizeOf(path) {
  const stats = lstatSync(path);
  if (!stats.isDirectory()) return stats.size;
  return readdirSync(path).reduce((total, entry) => total + sizeOf(`${path}/${entry}`), 0);
}
const MB = 1024 * 1024;
const total = sizeOf(out);
if (total > 400 * MB) {
  const biggest = readdirSync(out)
    .map((entry) => ({ entry, size: sizeOf(`${out}/${entry}`) }))
    .sort((a, b) => b.size - a.size)
    .slice(0, 5)
    .map(({ entry, size }) => `  ${entry} : ${Math.round(size / MB)} Mo`)
    .join("\n");
  console.error(`Release anormalement lourde (${Math.round(total / MB)} Mo). Plus gros éléments :\n${biggest}`);
  console.error("Retirer du dossier du projet les archives ou copies du projet, puis relancer pnpm build.");
  process.exit(1);
}
console.log(`Release assemblée dans ${out}/ (${commit}, ${Math.round(total / MB)} Mo)`);

// Native modules (argon2, sharp) are installed for the build machine only.
if (process.platform !== "linux") {
  console.warn(
    `Attention : release construite sur ${process.platform}. Ses modules natifs ne fonctionnent pas sur le serveur Linux du cPanel. ` +
      "Pour la production, utiliser le workflow GitHub « Release package » ou « Deploy ».",
  );
}

// Optional compressed package for an upload through the cPanel File Manager.
if (process.argv.includes("--archive")) {
  const archive = "portfolio-release.tar.gz";
  rmSync(archive, { force: true });
  execSync(`tar -czf ${archive} -C ${out} .`, { stdio: "inherit" });
  console.log(`Archive prête : ${archive} (${Math.round(statSync(archive).size / MB)} Mo)`);
}
